(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-722":{scenario:{company:"Bệnh viện Đa khoa Cẩm Giang Xanh",supervisor:{name:"Hà Thị Mai Phương",role:{vi:"Trưởng phòng Kế hoạch tổng hợp",en:"Head of General Planning Department"}},ref_code:"BM-3307",title:{vi:"Đúng phòng cách ly. Đúng công suất giường.",en:"Right isolation room. Right bed occupancy."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát bảng điều phối giường BM-3307 của khoa Nội tổng hợp. Người bệnh mới nhập viện (hư cấu) nghi lao phổi, ho kéo dài, xét nghiệm AFB đang chờ kết quả. Báo cáo tháng 6 (30 ngày): khoa có 40 giường kế hoạch, kê thêm 2 giường tạm, tổng 1092 ngày điều trị nội trú. Sửa loại phòng ngừa cách ly và công suất sử dụng giường, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are reviewing bed management board BM-3307 for the general internal medicine ward. A newly admitted (fictional) patient has suspected pulmonary tuberculosis with a prolonged cough, AFB test pending. June report (30 days): 40 planned beds, 2 temporary extra beds, 1092 inpatient days in total. Correct the isolation precaution type and the bed occupancy rate, then write an evidence-based report."},reference_title:{vi:"Quy trình điều phối giường & kiểm soát nhiễm khuẩn · BM-3307",en:"Bed management & infection control procedure · BM-3307"},fields:[{id:"ISOLATION",label:{vi:"Loại phòng ngừa cách ly",en:"Isolation precaution type"},initial:"Droplet",expected:"Airborne",choices:["Contact","Droplet","Airborne"],reference:"Bảng phân loại cách ly theo đường lây",hint:{vi:"Vi khuẩn lao lây qua hạt nhân giọt bắn rất nhỏ lơ lửng lâu trong không khí, cần phòng áp lực âm.",en:"TB spreads through tiny droplet nuclei that stay suspended in the air and needs a negative-pressure room."}},{id:"BED_OCC",label:{vi:"Công suất sử dụng giường (%)",en:"Bed occupancy rate (%)"},initial:"86.7",expected:"91",reference:"Báo cáo hoạt động khoa tháng 6",ref_value:{vi:"1092 ngày điều trị; 40 giường kế hoạch; 2 giường kê thêm; kỳ 30 ngày",en:"1092 inpatient days; 40 planned beds; 2 extra beds; 30-day period"},hint:{vi:"Mẫu số dùng số giường kế hoạch được giao, không cộng giường kê tạm.",en:"The denominator uses the assigned planned beds, not the temporary extra beds."}}],sop32:{vi:"Công suất sử dụng giường (%) = tổng ngày điều trị nội trú / (số giường kế hoạch x số ngày trong kỳ) x 100; giường kê thêm không đưa vào mẫu số (quy ước mô phỏng).",en:"Bed occupancy (%) = total inpatient days / (planned beds x days in period) x 100; temporary extra beds are excluded from the denominator (training convention)."},context:{label:"HIS / BM-3307",metrics:[{label:{vi:"Giường kế hoạch",en:"Planned beds"},value:"40"},{label:{vi:"Ngày điều trị tháng 6",en:"June inpatient days"},value:"1092"},{label:{vi:"Phòng áp lực âm trống",en:"Free negative-pressure room"},value:"1 (A12)"}]},crisis:{vi:"Phó giám đốc nhắn: “Phòng áp lực âm A12 đang giữ cho người nhà một lãnh đạo nằm theo yêu cầu. Xếp người bệnh nghi lao vào phòng 2 giường, cho đeo khẩu trang là được, đừng làm to chuyện.”",en:"The deputy director messages you: “Negative-pressure room A12 is reserved for a VIP's relative on request. Put the suspected TB patient in a two-bed room with a mask and don't make a fuss.”"},options:{safe:{vi:"Không xếp vào phòng thường; báo ngay khoa Kiểm soát nhiễm khuẩn và trực lãnh đạo, dùng phòng A12 theo chỉ định lâm sàng và đề xuất giường phù hợp khác cho người bệnh theo yêu cầu.",en:"Do not use a regular room; alert infection control and the duty director, assign A12 by clinical need and propose another suitable bed for the on-request patient."},shortcut:{vi:"Xếp người bệnh nghi lao vào phòng 2 giường, phát khẩu trang và ghi chú theo dõi.",en:"Place the suspected TB patient in a two-bed room, hand out masks and note it for follow-up."},wait:{vi:"Để người bệnh chờ ở hành lang khoa Cấp cứu cho đến khi lãnh đạo tự quyết định.",en:"Leave the patient waiting in the emergency corridor until management decides."}},questions:{vi:["Vì sao bạn thay đổi loại phòng ngừa cách ly? Đặc điểm lây truyền nào chứng minh lựa chọn đó?","Trình bày cách tính công suất sử dụng giường và cách xử lý khi phòng cách ly bị giữ cho mục đích không theo chỉ định chuyên môn."],en:["Why did you change the isolation precaution type? Which transmission feature supports your choice?","Explain how you calculated bed occupancy and how you handle an isolation room held for a non-clinical reason."]},hints:{vi:["Đặt chẩn đoán nghi ngờ cạnh bảng phân loại cách ly và xác định đường lây chính của bệnh.","Theo SOP mục 3.2: kiểm tra lại mẫu số, chỉ dùng giường kế hoạch nhân số ngày trong kỳ.","Đọc lại SOP mục 4.2: phòng cách ly được phân bổ theo chỉ định lâm sàng, mọi áp lực khác phải báo cáo."],en:["Put the suspected diagnosis next to the isolation table and identify the main transmission route.","Per SOP 3.2: check the denominator and use planned beds times days in the period.","Re-read SOP 4.2: isolation rooms are allocated by clinical need; any other pressure must be escalated."]}},learning:{summary:{vi:"Chuyên viên điều phối vận hành bệnh viện và phòng khám bảo đảm dòng người bệnh thông suốt: phân bổ giường, lập lịch khám và phòng mổ, phối hợp xét nghiệm, chẩn đoán hình ảnh, vận chuyển, vệ sinh và theo dõi chỉ số vận hành hằng ngày. Công việc giúp giảm thời gian chờ, dùng hiệu quả nguồn lực và giữ an toàn người bệnh. Nghề đòi hỏi tư duy dữ liệu, hiểu quy định kiểm soát nhiễm khuẩn và khả năng ra quyết định nhanh dưới áp lực.",en:"A hospital and clinic operations coordinator keeps patient flow moving: allocating beds, scheduling clinics and operating rooms, coordinating laboratory, imaging, transport and cleaning, and tracking daily operating metrics. The work reduces waiting times, uses resources efficiently and keeps patients safe. The role needs data thinking, knowledge of infection control rules and the ability to decide quickly under pressure."},responsibilities:{vi:["Điều phối giường cho nhập viện, chuyển khoa và ra viện theo mức ưu tiên lâm sàng.","Lập và điều chỉnh lịch phòng khám, phòng mổ, cân đối nhân lực theo dự báo lượt khám.","Theo dõi công suất giường, ngày điều trị trung bình, thời gian chờ và cảnh báo quá tải.","Phối hợp các bộ phận hỗ trợ: xét nghiệm, chẩn đoán hình ảnh, vận chuyển, vệ sinh, dinh dưỡng.","Kích hoạt kế hoạch ứng phó khi quá tải, sự cố hoặc tiếp nhận cấp cứu hàng loạt."],en:["Allocate beds for admissions, transfers and discharges by clinical priority.","Build and adjust clinic and operating room schedules and balance staff against visit forecasts.","Track bed occupancy, average length of stay and waiting times and flag overload.","Coordinate support services: laboratory, imaging, transport, cleaning and nutrition.","Activate response plans for overload, incidents or mass casualty events."]},competencies:[{name:{vi:"Quản lý dòng người bệnh",en:"Patient flow management"},desc:{vi:"Nhìn toàn bộ chuỗi từ cấp cứu đến ra viện, phát hiện điểm nghẽn và điều chỉnh kịp thời.",en:"See the whole chain from emergency to discharge, spot bottlenecks and adjust in time."}},{name:{vi:"Phân tích chỉ số vận hành",en:"Operational analytics"},desc:{vi:"Tính đúng công suất giường, ngày điều trị trung bình, thời gian chờ và giải thích xu hướng.",en:"Compute bed occupancy, length of stay and waiting times correctly and explain trends."}},{name:{vi:"Kiểm soát nhiễm khuẩn trong điều phối",en:"Infection control in placement"},desc:{vi:"Xếp giường theo đường lây: tiếp xúc, giọt bắn, không khí; ưu tiên phòng cách ly đúng chỉ định.",en:"Place patients by transmission route: contact, droplet, airborne; allocate isolation by indication."}},{name:{vi:"Phối hợp liên khoa",en:"Cross-department coordination"},desc:{vi:"Làm việc với bác sĩ, điều dưỡng, hậu cần bằng thông tin rõ ràng và cam kết thời gian.",en:"Work with doctors, nurses and logistics using clear information and time commitments."}},{name:{vi:"Liêm chính & bảo mật",en:"Integrity & confidentiality"},desc:{vi:"Phân bổ nguồn lực công bằng theo chuyên môn, bảo mật thông tin người bệnh và báo cáo áp lực sai.",en:"Allocate resources fairly by clinical need, protect patient data and escalate improper pressure."}}],knowledge:{vi:["Luật Khám bệnh, chữa bệnh số 15/2023/QH15: quyền người bệnh, bảo mật thông tin, tổ chức cơ sở khám chữa bệnh.","Bộ tiêu chí chất lượng bệnh viện Việt Nam ban hành theo Quyết định 6858/QĐ-BYT năm 2016.","Thông tư 16/2018/TT-BYT về kiểm soát nhiễm khuẩn trong cơ sở khám bệnh, chữa bệnh.","Phòng ngừa chuẩn và phòng ngừa dựa trên đường lây: tiếp xúc, giọt bắn, không khí.","Chỉ số vận hành: công suất sử dụng giường, ngày điều trị trung bình, thời gian chờ, tỷ lệ hủy hoãn mổ."],en:["Law on Medical Examination and Treatment No. 15/2023/QH15: patient rights, confidentiality, facility organisation.","Vietnam hospital quality criteria issued under Decision 6858/QD-BYT in 2016.","Circular 16/2018/TT-BYT on infection control in healthcare facilities.","Standard precautions and transmission-based precautions: contact, droplet and airborne.","Operating metrics: bed occupancy, average length of stay, waiting time and surgery cancellation rate."]},tools:["Hệ thống thông tin bệnh viện (HIS)","Bảng điều phối giường điện tử","Phần mềm lập lịch phòng khám, phòng mổ","Bảng điều khiển chỉ số vận hành","Bảng tính điện tử"],kpis:{vi:["Thời gian chờ nhập giường từ khoa Cấp cứu.","Công suất sử dụng giường trong vùng mục tiêu của bệnh viện.","Tỷ lệ người bệnh ra viện trước 12 giờ trưa.","Tỷ lệ hủy, hoãn mổ do lỗi điều phối (mục tiêu bằng 0)."],en:["Waiting time for a bed from the emergency department.","Bed occupancy within the hospital's target range.","Share of patients discharged before noon.","Surgery cancellations or delays caused by coordination errors (target zero)."]},day:[{time:"07:30",vi:"Dự giao ban, cập nhật giường trống, giường dự kiến ra viện và ca cấp cứu chờ nhập.",en:"Attend the morning huddle and update free beds, expected discharges and waiting admissions."},{time:"09:00",vi:"Điều phối chuyển khoa, xếp phòng cách ly theo đường lây cho ca mới.",en:"Coordinate transfers and assign isolation rooms by transmission route for new cases."},{time:"11:00",vi:"Theo dõi tiến độ ra viện, phối hợp vệ sinh buồng và vận chuyển người bệnh.",en:"Track discharges and coordinate room cleaning and patient transport."},{time:"14:00",vi:"Chốt lịch mổ ngày mai, kiểm tra giường hồi sức và nhân lực gây mê.",en:"Finalise tomorrow's surgery list and check recovery beds and anaesthesia staff."},{time:"16:30",vi:"Cập nhật bảng chỉ số, báo cáo điểm nghẽn và đề xuất cải tiến.",en:"Update the dashboard, report bottlenecks and propose improvements."}],mistakes:{vi:["Dùng số giường thực kê làm mẫu số khiến công suất giường bị báo thấp hơn thực tế.","Nhầm phòng ngừa giọt bắn với phòng ngừa qua không khí khi xếp người bệnh nghi lao, sởi.","Ưu tiên giường theo quan hệ thay vì theo mức độ cấp thiết lâm sàng."],en:["Using actual beds as the denominator so occupancy is reported lower than reality.","Confusing droplet and airborne precautions when placing suspected TB or measles patients.","Allocating beds by connections instead of clinical urgency."]},career:[{vi:"Nhân viên điều phối người bệnh",en:"Patient flow assistant"},{vi:"Chuyên viên điều phối vận hành bệnh viện",en:"Hospital operations coordinator"},{vi:"Trưởng nhóm điều phối giường và phòng mổ",en:"Bed and theatre coordination lead"},{vi:"Trưởng phòng Kế hoạch tổng hợp hoặc Giám đốc vận hành",en:"Head of planning or chief operating officer"}],glossary:[{term:"Bed occupancy",vi:"Công suất sử dụng giường: tỷ lệ ngày điều trị thực tế so với khả năng giường kế hoạch trong kỳ.",en:"Ratio of actual inpatient days to planned bed capacity over a period."},{term:"ALOS",vi:"Ngày điều trị trung bình: tổng ngày điều trị chia cho số người bệnh ra viện trong kỳ.",en:"Average length of stay: total inpatient days divided by discharges in the period."},{term:"Airborne precautions",vi:"Phòng ngừa lây qua không khí: phòng áp lực âm, khẩu trang N95, hạn chế di chuyển người bệnh.",en:"Precautions for airborne spread: negative-pressure room, N95 respirators, limited patient movement."},{term:"Patient flow",vi:"Dòng di chuyển của người bệnh qua các khâu khám, chẩn đoán, điều trị và ra viện.",en:"Movement of patients through assessment, diagnostics, treatment and discharge."},{term:"Surge plan",vi:"Kế hoạch tăng công suất khẩn cấp khi lượng người bệnh vượt khả năng thông thường.",en:"Emergency plan to expand capacity when patient volume exceeds normal limits."}],quiz:[{q:{vi:"Khoa có 30 giường kế hoạch, tháng có 31 ngày, tổng 837 ngày điều trị nội trú. Công suất sử dụng giường là bao nhiêu?",en:"A ward has 30 planned beds, a 31-day month and 837 inpatient days. What is the bed occupancy?"},options:{vi:["93%","84%","87%","90%"],en:["93%","84%","87%","90%"]},answer:3,explain:{vi:"Công suất = 837 / (30 giường x 31 ngày) x 100 = 837 / 930 x 100 = 90%.",en:"837 / (30 x 31) x 100 = 837 / 930 x 100 = 90%."}},{q:{vi:"Người bệnh nghi lao phổi cần áp dụng loại phòng ngừa nào khi xếp giường?",en:"Which precaution applies when placing a patient with suspected pulmonary TB?"},options:{vi:["Phòng ngừa tiếp xúc","Phòng ngừa qua không khí","Phòng ngừa giọt bắn","Chỉ cần phòng ngừa chuẩn"],en:["Contact precautions","Airborne precautions","Droplet precautions","Standard precautions only"]},answer:1,explain:{vi:"Lao phổi lây qua hạt nhân giọt bắn lơ lửng trong không khí nên cần phòng áp lực âm và khẩu trang N95.",en:"Pulmonary TB spreads by airborne droplet nuclei, so it needs a negative-pressure room and N95 respirators."}},{q:{vi:"Một người quen nhờ bạn tra cứu chẩn đoán của người bệnh khác trên HIS. Bạn làm gì?",en:"An acquaintance asks you to look up another patient's diagnosis in the HIS. What do you do?"},options:{vi:["Từ chối và giải thích thông tin người bệnh chỉ được cung cấp theo quy định","Tra cứu nhưng chỉ nói miệng","Chụp màn hình gửi riêng","Nhờ đồng nghiệp tra hộ"],en:["Refuse and explain patient data is only released per regulations","Look it up and only tell them verbally","Send a private screenshot","Ask a colleague to look it up"]},answer:0,explain:{vi:"Thông tin người bệnh được pháp luật bảo vệ; chỉ truy cập khi có nhiệm vụ và cung cấp theo đúng quy định.",en:"Patient information is protected by law; access it only for duty and release it only as regulations allow."}},{q:{vi:"Ngày điều trị trung bình (ALOS) được tính như thế nào?",en:"How is average length of stay (ALOS) calculated?"},options:{vi:["Số giường chia số người bệnh","Tổng ngày điều trị chia số giường","Tổng ngày điều trị chia số người bệnh ra viện","Số người bệnh nhập chia số ngày"],en:["Beds divided by patients","Inpatient days divided by beds","Inpatient days divided by discharges","Admissions divided by days"]},answer:2,explain:{vi:"ALOS bằng tổng số ngày điều trị nội trú của người bệnh ra viện chia cho số người bệnh ra viện trong kỳ.",en:"ALOS equals total inpatient days of discharged patients divided by the number of discharges in the period."}}],tools_en:["Hospital information system (HIS)","Electronic bed management board","Clinic and operating room scheduling software","Operational KPI dashboard","Spreadsheets"]}}})})(window.KKR);
